mapper.select:
SELECT TENANT.ID, TENANT.CREATOR, TENANT.CREATE_TIME, TENANT.MODIFIER, TENANT.MODIFY_TIME, TENANT.LOGIC_DEL, TENANT.REC_VER, TENANT.BUILD_IN, TENANT.TENANT_ID, TENANT.CODE, TENANT.NAME, TENANT.TYPE, TENANT.STATUS, TENANT.REMARK, TENANT.CONTACT_NAME, TENANT.CONTACT_TEL, TENANT.CONTACT_EMAIL, TENANT.ADDRESS, TENANT.BUSINESS_HOURS_FROM, TENANT.TENANT_ID FROM sys_tenant TENANT LEFT JOIN sys_tenant_user TU ON TENANT.id = TU.TENANT_ID WHERE LOGIC_DEL = 0
AND TU.USER_ID = #{dto.userId}
AND TENANT.ID = #{dto.id}
